import {
  TableCellType,
  TableDataType,
  TableHeaderType,
} from 'components/Table/types';
import { FilterOption } from 'models/Filters';

import { TableCustomizationGroup } from '../tableCustomization.types';

const MERGE_CONTEXT_LABELS: Record<string, string> = {
  'Investment [Mio USD]': 'Investment',
  'QWOA [#]': 'QWOA',
};

const SUB_HEADER_UNIT_VALUES = new Set(['k hl', '%']);

const isEmptySubHeaderCell = (cell: unknown): boolean =>
  Array.isArray(cell) && cell.length === 0;

const isTableCellType = (cell: unknown): cell is TableCellType =>
  typeof cell === 'object' && cell !== null && !Array.isArray(cell);

const getSubHeaderCell = (
  subHeaderRow: Record<string, unknown> | undefined,
  columnId: string,
): TableCellType | undefined => {
  if (!subHeaderRow) return undefined;

  const cell = subHeaderRow[columnId];
  if (!cell || isEmptySubHeaderCell(cell) || !isTableCellType(cell)) {
    return undefined;
  }

  return cell;
};

const stripTrailingBracketSuffix = (value: string): string => {
  const lastOpenBracket = value.lastIndexOf('[');
  const lastCloseBracket = value.lastIndexOf(']');

  if (
    lastOpenBracket === -1 ||
    lastCloseBracket <= lastOpenBracket ||
    lastCloseBracket !== value.length - 1
  ) {
    return value.trim();
  }

  return value.slice(0, lastOpenBracket).trimEnd();
};

const getMergeContextLabel = (mergeValue: string): string =>
  MERGE_CONTEXT_LABELS[mergeValue] ?? stripTrailingBracketSuffix(mergeValue);

const buildColumnLabel = (
  title: string,
  contextLabel: string | undefined,
  standaloneLabel: string | undefined,
  duplicateTitles: Set<string>,
): string => {
  if (standaloneLabel) {
    return standaloneLabel;
  }

  if (contextLabel && duplicateTitles.has(title)) {
    return `${title} [${contextLabel}]`;
  }

  return title;
};

const getContextLabel = (
  standaloneLabel: string | undefined,
  activeMergeContext: string | undefined,
  subHeaderCell: TableCellType | undefined,
): string | undefined => {
  if (standaloneLabel !== undefined) {
    return undefined;
  }

  if (activeMergeContext !== undefined) {
    return activeMergeContext;
  }

  if (subHeaderCell?.value) {
    return getMergeContextLabel(String(subHeaderCell.value));
  }

  return undefined;
};

const getDuplicateTitles = (children: TableHeaderType[]): Set<string> => {
  const titleCounts = children.reduce<Record<string, number>>(
    (counts, child) => {
      const title = child.title ?? '';
      counts[title] = (counts[title] ?? 0) + 1;
      return counts;
    },
    {},
  );

  return new Set(
    Object.entries(titleCounts)
      .filter(([, count]) => count > 1)
      .map(([title]) => title),
  );
};

const buildGroupValues = (
  children: TableHeaderType[],
  subHeaderRow: Record<string, unknown> | undefined,
): TableCustomizationGroup['values'] => {
  const duplicateTitles = getDuplicateTitles(children);
  let activeMergeContext: string | undefined;

  return children
    .filter((child): child is TableHeaderType & { id: string } => !!child.id)
    .map((child) => {
      const subHeaderCell = getSubHeaderCell(subHeaderRow, child.id);

      if (subHeaderCell?.mergeCol) {
        activeMergeContext = getMergeContextLabel(
          String(subHeaderCell.value ?? ''),
        );
      } else if (
        subHeaderCell?.value !== undefined &&
        !subHeaderCell.mergeCol
      ) {
        activeMergeContext = undefined;
      }

      const subHeaderValue =
        subHeaderCell?.value === undefined
          ? undefined
          : String(subHeaderCell.value);

      const standaloneLabel =
        subHeaderValue !== undefined &&
        !subHeaderCell?.mergeCol &&
        subHeaderValue !== child.title &&
        !SUB_HEADER_UNIT_VALUES.has(subHeaderValue)
          ? subHeaderValue
          : undefined;

      const contextLabel = getContextLabel(
        standaloneLabel,
        activeMergeContext,
        subHeaderCell,
      );

      return {
        value: child.id,
        label: buildColumnLabel(
          child.title,
          contextLabel,
          standaloneLabel,
          duplicateTitles,
        ),
      };
    });
};

const buildGroupsFromFilter = (
  filter: FilterOption[],
): TableCustomizationGroup[] =>
  filter
    .map((filterGroup) => ({
      group: filterGroup.group,
      values: filterGroup.values.map((option) => ({
        value: String(option.value),
        label: String(option.label),
      })),
    }))
    .filter((group) => group.values.length > 0);

export const buildTableCustomizationGroups = (
  data: TableDataType,
  filter?: FilterOption[],
): TableCustomizationGroup[] => {
  if (filter?.length) {
    return buildGroupsFromFilter(filter);
  }

  if (!data.header?.length) {
    return [];
  }

  const subHeaderRow = data.rows?.[0]?.[0] as
    | Record<string, unknown>
    | undefined;

  return data.header
    .filter((headerItem) => headerItem.children?.length)
    .map((headerItem) => ({
      group: headerItem.title,
      values: buildGroupValues(headerItem.children ?? [], subHeaderRow),
    }))
    .filter((group) => group.values.length > 0);
};

export const getAllColumnIdsFromGroups = (
  groups: TableCustomizationGroup[],
): string[] =>
  groups.flatMap((group) => group.values.map((value) => value.value));
